import fs from 'node:fs';

const source = fs.readFileSync('mt-rainier-seattle-2026.html', 'utf8');
const seattleRoot = 'assets/img/mt-rainier-seattle-2026';

function replaceBlock(html, start, end, replacement) {
  const a = html.indexOf(start);
  const b = html.indexOf(end, a + start.length);
  if (a < 0 || b < 0) throw new Error(`Missing block: ${start}`);
  return `${html.slice(0, a)}${replacement}${html.slice(b + end.length)}`;
}

function img(root, file, href, title, credit) {
  return { src: `${root}/${file}`, href, title, credit: `${credit} · Google Images source`, alt: title };
}

function carousel(id, images, hero = false) {
  const figures = images.map((p, i) => `<figure><a href="${p.href}" target="_blank" rel="noreferrer"><img src="${p.src}" alt="${p.alt}"${i ? ' loading="lazy"' : hero ? ' fetchpriority="high"' : ''}></a><figcaption>${hero ? `<span class="cap-day">${p.day || 'Pacific Northwest'}</span>` : ''}<strong>${p.title}</strong><span${hero ? ' class="cap-desc"' : ''}>${p.credit}</span></figcaption></figure>`).join('');
  const dots = images.map((_, i) => `<button type="button" class="dot" data-i="${i}" aria-label="Photo ${i + 1}"></button>`).join('');
  return `<div class="carousel${hero ? ' pvcar' : ''}" id="${id}" data-n="${images.length}"><div class="track">${figures}</div><button type="button" class="nav prev" aria-label="Previous photo">&lsaquo;</button><button type="button" class="nav next" aria-label="Next photo">&rsaquo;</button><div class="counter"><span class="cur">1</span> / ${images.length}</div><div class="dots">${dots}</div></div>`;
}

function extractSeattleImages(prefix) {
  const figures = [...source.matchAll(/<figure><a[\s\S]*?<\/figure>/g)].map(m => m[0]);
  return figures.filter(f => f.includes(`/${prefix}`)).map((f) => ({ raw: f }));
}

function rawCarousel(id, images) {
  const figures = images.map(x => x.raw).join('');
  const dots = images.map((_, i) => `<button type="button" class="dot" data-i="${i}" aria-label="Photo ${i + 1}"></button>`).join('');
  return `<div class="carousel" id="${id}" data-n="${images.length}"><div class="track">${figures}</div><button type="button" class="nav prev" aria-label="Previous photo">&lsaquo;</button><button type="button" class="nav next" aria-label="Next photo">&rsaquo;</button><div class="counter"><span class="cur">1</span> / ${images.length}</div><div class="dots">${dots}</div></div>`;
}

const seattleMonday = extractSeattleImages('google_seattle_monday_');
const seattleTuesday = extractSeattleImages('google_c5_');

function card(kicker, title, body) {
  return `<article class="ocard"><p class="eyebrow">${kicker}</p><h4>${title}</h4><p>${body}</p></article>`;
}

function section(id, eyebrow, title, lead, body, cls = 'divider') {
  return `<section id="${id}"${cls ? ` class="${cls}"` : ''}><div class="section-label"><p class="eyebrow">${eyebrow}</p><h2>${title}</h2><p>${lead}</p></div>${body}</section>`;
}

function day(d) {
  const facts = d.facts.map(([k, v]) => `<div><span>${k}</span><strong>${v}</strong></div>`).join('');
  const links = d.links.map(([t, u]) => `<a href="${u}" target="_blank" rel="noreferrer">${t}</a>`).join('');
  const photos = d.rawPhotos ? rawCarousel(`${d.id}-car`, d.rawPhotos) : carousel(`${d.id}-car`, d.photos);
  return `<article class="day ${d.cls}" id="${d.id}"><div class="day-head"><div class="day-badge">${d.badge}</div><div class="day-title"><p class="eyebrow">${d.date}</p><h3>${d.title}</h3><p class="feel">${d.feel}</p></div></div><div class="day-info"><div class="facts">${facts}</div><p class="note">${d.note}</p></div><div class="spots-wrap"><section class="spot"><div class="spot-head"><div><h4 class="spot-name">${d.spot}</h4></div><div class="explore"><a class="xg" href="https://www.google.com/search?tbm=isch&amp;q=${encodeURIComponent(`${d.spot} professional landscape photography`)}" target="_blank" rel="noreferrer">Photos</a></div></div>${photos}<div class="spot-grid"><div class="spot-info"><div class="kv"><span>Exact flow</span><p>${d.flow}</p></div><div class="kv climate"><span>Reality check</span><p>${d.reality}</p></div><div class="callout save"><b>Cost / access</b> ${d.cost}</div><div class="callout splurge"><b>Food</b> ${d.food}</div><div class="bloglinks"><p class="mini-h">Check before leaving</p>${links}</div></div><div class="spot-map"><div class="mapwrap"><iframe class="gmap" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://www.google.com/maps?q=${encodeURIComponent(d.map)}&amp;z=9&amp;output=embed" title="Map of ${d.spot}"></iframe></div><a class="gmap-btn" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(d.map)}" target="_blank" rel="noreferrer">&#128205; Open in Google Maps &#8617;</a></div></div></section></div></article>`;
}

